#include "cyd_time_platform.h"
#include "headers.inc"
static unsigned backend_initializations,backend_applies,backend_restarts,backend_notifies;
static esp_err_t fail_backend;
static esp_err_t fail_backend_init;
static native_time_sntp_sync_cb_t backend_callback;
static void *backend_context;
static native_time_sntp_config_t backend_config;
static void(*during_apply)(void);
esp_err_t native_time_sntp_init(native_time_sntp_sync_cb_t cb,void *ctx){backend_initializations++;backend_callback=cb;backend_context=ctx;return fail_backend_init;}
void native_time_sntp_notify_network_ready(void){backend_notifies++;}
esp_err_t native_time_sntp_apply(const native_time_sntp_config_t *config){assert(backend_notifies);backend_applies++;backend_config=*config;if(during_apply){void(*hook)(void)=during_apply;during_apply=NULL;hook();}return fail_backend;}
esp_err_t native_time_sntp_restart(void){assert(backend_notifies);backend_restarts++;return fail_backend;}
#define time host_time
#include "settings.inc"
#include "service.inc"
#undef time

static void defaults(time_settings_t *s){time_settings_defaults(s);assert(time_settings_valid(s));}
static time_snapshot_t snapshot(void){time_snapshot_t s;assert(time_service_snapshot(&s));assert(s.available);return s;}
static void start(bool online){if(online)time_service_notify_network(true);assert(time_service_start()==ESP_OK);step();}
static void cold_ram(void){portENTER_CRITICAL(&s_snapshot_lock);s_initialized=false;s_revision=0;memset(&s_settings,0,sizeof(s_settings));portEXIT_CRITICAL(&s_snapshot_lock);}
static void set_next_config(void){time_settings_t s;defaults(&s);strcpy(s.servers[0],"new.example");s.utc_offset_minutes=345;assert(time_service_save_settings(&s)==ESP_OK);}
static void *save_thread(void *arg){assert(time_settings_save(arg)==ESP_OK);return NULL;}

